    border-bottom: 0.24mm solid var(--cd-document-border) !important;
    background: none !important;
}

@page {
    size: A4;
    margin: 0;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
}

/*
 * IMPORTANT FOR FRAPPE PDF:
 * Frappe reads the individual margin-* and page-size declarations from
 * .print-format and passes them to the PDF engine. Do not replace these with
 * only the shorthand `margin: 0`.
 */
.print-format {
    width: 210mm !important;
    min-width: 210mm !important;
    margin-top: 0mm !important;
    margin-right: 0mm !important;
    margin-bottom: 0mm !important;
    margin-left: 0mm !important;
    padding: 0 !important;
    page-size: A4;
}

.cd-po-root,
.cd-po-root * {
    box-sizing: border-box;
}

.cd-po-root {
    --cd-document-ink: #202020;
    --cd-document-border: #202020;
    --cd-document-surface: #f1f1f1;
    --cd-document-accent: #e2a2f5;

    width: 210mm;
    margin: 0;
    padding: 0;

    color: var(--cd-document-ink);
    background: #fff;

    font-family:
        "TH Sarabun Document",
        "Noto Sans Thai",
        "TH Sarabun New",
        "TH SarabunPSK",
        sans-serif;

    font-size: 4.22mm;
    font-weight: 400;
    line-height: 1;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* =========================================================
   FLOW TABLE — SOURCE OF TRUTH FOR PRINT / PDF

   There is only one item stream. The rendering engine decides where an item
   fits from its ACTUAL rendered height. No row is assigned to a page by Jinja.
   ========================================================= */

.po-flow-source {
    display: block;
    width: 210mm;
}

.page-flow-table {
    width: 210mm;
    margin: 0;
    padding: 0;

    border: 0;
    border-collapse: collapse;
    border-spacing: 0;
    table-layout: fixed;
}

.page-flow-table>thead {
    display: table-header-group;
}

.page-flow-table>tfoot {
    display: table-footer-group;
}

.page-flow-table>tbody {
    display: table-row-group;
}

.page-flow-table>thead>tr,
.page-flow-table>tfoot>tr,
.page-flow-table>tbody>tr {
    border: 0;
}

.page-flow-group-cell {
    width: 210mm;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    vertical-align: top !important;
}

.flow-item-fragment {
    page-break-inside: avoid !important;
    break-inside: avoid-page !important;
}

.flow-item-fragment>td {
    page-break-inside: avoid !important;
    break-inside: avoid-page !important;
}

.flow-item-table-wrap {
    width: 189.90mm;
    margin-left: 13.81mm;
    page-break-inside: avoid !important;
    break-inside: avoid-page !important;
}

.document-main-head,
.document-main-foot,
.preview-document-main {
    width: 189.90mm;
    margin-left: 13.81mm;
}

.info-box {
    width: 100%;
    border: 0.24mm solid var(--cd-document-border);
    border-radius: 2.18mm;
    background: #fff;
}

/* =========================================================
   DOCUMENT META
   ========================================================= */

.document-meta-box {
    padding: 2.75mm 3.60mm 2.55mm;
}

.meta-grid {
    width: 100%;

    display: -webkit-flex;
    display: flex;
    -webkit-flex-wrap: wrap;
    flex-wrap: wrap;

    margin: -1.00mm -2.10mm;
}

.meta-item {
    min-width: 0;
    width: 25%;

    display: -webkit-flex;
    display: flex;
    -webkit-align-items: center;
    align-items: center;

    padding: 1.00mm 2.10mm;
}

.meta-label {
    -webkit-flex: 0 0 auto;
    flex: 0 0 auto;
    min-width: 0;
    margin-right: 1.80mm;

    font-size: 4.10mm;
    font-weight: 700;
    line-height: 4.65mm;
    white-space: nowrap;
}

.meta-value {
    -webkit-flex: 1 1 auto;
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;

    font-size: 4.10mm;
    font-weight: 400;
    line-height: 4.65mm;
    white-space: nowrap;
    text-overflow: clip;
}

.meta-item:nth-child(5) .meta-value,
.meta-item:nth-child(7) .meta-value {
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.meta-value-strong {
    font-size: 4.45mm;
    font-weight: 700;
}

.credit-pill {
    display: inline-block;
    min-width: 17.80mm;
    padding: 0.25mm 2.15mm 0.45mm;

    border: 0.24mm solid var(--cd-document-border);
    border-radius: 4mm;

    line-height: 4.10mm;
    text-align: center;
    white-space: nowrap;
}

/* =========================================================
   SUPPLIER / SHIP TO / CONTACT
   ========================================================= */

.address-contact-box {
    margin-top: 2.40mm;
    padding: 3.00mm 3.60mm 3.20mm;
}

.address-grid {
    width: 100%;

    display: -webkit-flex;
    display: flex;
    -webkit-align-items: stretch;
    align-items: stretch;
}

.supplier-section,
.shipto-section {
    -webkit-flex: 1.35 1 0;
    flex: 1.35 1 0;
}

.contact-section {
    -webkit-flex: 0.80 1 0;
    flex: 0.80 1 0;
}

.address-section {
    min-width: 0;
    height: auto;
    padding: 0 3.60mm;
    overflow: visible;
}

.address-section:first-child {
    padding-left: 0;
}

.address-section:last-child {
    padding-right: 0;
}

.address-section+.address-section {
    border-left: 0.24mm solid var(--cd-document-border);
}

.section-heading {
    display: -webkit-flex;
    display: flex;
    -webkit-flex-wrap: wrap;
    flex-wrap: wrap;
    -webkit-align-items: baseline;
    align-items: baseline;

    margin: 0 0 1.20mm;
}

.section-heading>*+* {
    margin-left: 1.80mm;
}

.section-title {
    font-size: 4.22mm;
    font-weight: 700;
    line-height: 4.80mm;
    white-space: nowrap;
}

.supplier-code {
    font-size: 4.10mm;
    font-weight: 400;
    line-height: 4.80mm;
    white-space: nowrap;
}

.section-primary {
    margin: 0 0 0.80mm;

    font-size: 4.22mm;
    font-weight: 400;
    line-height: 4.45mm;

    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.section-content {
    min-width: 0;
    margin: 0;
    padding: 0;

    font-size: 4.10mm;
    font-weight: 400;
    line-height: 4.20mm;

    white-space: normal;
    overflow: visible;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.address-display,
.contact-display {
    height: auto;
    min-height: 0;
    max-height: none;
}

.address-display p,
.contact-display p {
    margin: 0 !important;
    padding: 0 !important;
    font: inherit !important;
    line-height: inherit !important;
}

.address-display br,
.contact-display br {
    display: block !important;
}

/* =========================================================
   PRODUCT HEADER
   ========================================================= */

.product-head-wrap {
    width: 100%;
    margin-top: 3.20mm;
}

.product-head {
    width: 100%;
    height: 8.64mm;

    display: -webkit-flex;
    display: flex;

    border: 0.24mm solid var(--cd-document-border);
    border-radius: 2.18mm 2.18mm 0 0;
    background: var(--cd-document-surface);

    font-weight: 700;
    overflow: hidden;
}

.head-cell {
    min-width: 0;
    height: 8.16mm;

    display: -webkit-flex;
    display: flex;
    -webkit-align-items: center;
    align-items: center;
    -webkit-justify-content: center;
    justify-content: center;

    padding: 0.35mm 0.55mm;
    border-right: 0.24mm solid var(--cd-document-border);

    font-size: 4.05mm;
    line-height: 4mm;
    text-align: center;
    overflow: hidden;
}

.product-head .col-no {
    -webkit-flex: 0 0 9.50mm;
    flex: 0 0 9.50mm;
}

.product-head .col-item-code {
    -webkit-flex: 0 0 24mm;
    flex: 0 0 24mm;
}

.product-head .col-mat-code {
    -webkit-flex: 0 0 24mm;
    flex: 0 0 24mm;
}

.product-head .col-description {
    -webkit-flex: 0 0 46.40mm;
    flex: 0 0 46.40mm;
}

.product-head .col-quantity {
    -webkit-flex: 0 0 18mm;
    flex: 0 0 18mm;
}

.product-head .col-uom {
    -webkit-flex: 0 0 17mm;
    flex: 0 0 17mm;
}

.product-head .col-unit-price {
    -webkit-flex: 0 0 25.50mm;
    flex: 0 0 25.50mm;
}

.product-head .col-amount {
    -webkit-flex: 0 0 25.50mm;
    flex: 0 0 25.50mm;
}

.head-cell:last-child {
    border-right: 0;
}

/* =========================================================
   ITEM ROWS
   ========================================================= */

.item-lines {
    width: 100%;
    margin: 0;
    padding: 0;

    border: 0;
    border-collapse: separate;
    border-spacing: 0;
    table-layout: fixed;

    background: transparent;
}

.item-lines col.col-no {
    width: 9.50mm;
}

.item-lines col.col-item-code {
    width: 24mm;
}

.item-lines col.col-mat-code {
    width: 24mm;
}

.item-lines col.col-description {
    width: 46.40mm;
}

.item-lines col.col-quantity {
    width: 18mm;
}

.item-lines col.col-uom {
    width: 17mm;
}

.item-lines col.col-unit-price {
    width: 25.50mm;
}

.item-lines col.col-amount {
    width: 25.50mm;
}

.item-lines .item-row,
.item-lines .item-row td {
    page-break-inside: avoid !important;
    break-inside: avoid-page !important;
}

.item-lines td {
    margin: 0;

    border: 0 !important;
    border-right: 0.24mm solid var(--cd-document-border) !important;

    font-size: 4.10mm;
    font-weight: 400;
    line-height: 4.25mm;

    vertical-align: top !important;
}

.item-lines td:last-child {
    border-right: 0 !important;
}

.item-lines .item-row td {
    height: 8.50mm;
    padding: 2.00mm 1.15mm 0.65mm;
}

.item-lines .cell-no {
    text-align: center;
}

.item-lines .cell-item-code,
.item-lines .cell-mat-code {
    padding-left: 1.15mm;
    padding-right: 0.70mm;
    white-space: nowrap;
}

.item-lines .cell-description {
    padding-left: 1.35mm;
    padding-right: 1mm;
    white-space: normal;
    overflow: visible;
    overflow-wrap: anywhere;
    word-break: normal;
}

.item-lines .cell-quantity {
    text-align: right;
    white-space: nowrap;
}

.item-lines .cell-uom {
    text-align: center;
    white-space: nowrap;
}

.item-lines .cell-money {
    text-align: right;
    white-space: nowrap;
}

/* Each flow row contributes its real height. Never clip it. */
.flow-item-table-wrap {
    border-left: 0.24mm solid var(--cd-document-border);
    border-right: 0.24mm solid var(--cd-document-border);
    overflow: visible;
}

.flow-item-table {
    width: 100%;
    height: auto;
}

/* =========================================================
   SUMMARY + TOTAL
   ========================================================= */

