/* =========================================================
   BROWSER PREVIEW — EXPLICIT 210 x 297 mm PAGES
   ========================================================= */

.po-preview-pages,
.preview-prototype {
    display: none;
}

/* Make generated pages measurable without flashing them on screen. */
.cd-po-root.preview-measuring .po-preview-pages {
    display: block;
    position: absolute;
    left: -10000px;
    top: 0;
    visibility: hidden;
}

.cd-po-root.preview-ready .po-flow-source {
    display: none;
}

.cd-po-root.preview-ready .po-preview-pages {
    display: block;
}

.cd-po.preview-page,
.cd-po.preview-prototype {
    position: relative;
    width: 210mm;
    height: 297mm;
    min-height: 297mm;
    max-height: 297mm;
    margin: 0;
    padding: 0;
    overflow: hidden;

    color: var(--cd-document-ink);
    background: #fff;

    font-family:
        "TH Sarabun Document",
        "Noto Sans Thai",
        "TH Sarabun New",
        "TH SarabunPSK",
        sans-serif;

    font-size: 4.22mm;
    font-weight: 400;
    line-height: 1;

    page-break-after: always;
    break-after: page;

    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.cd-po.preview-page.last-page {
    page-break-after: auto;
    break-after: auto;
}

.preview-document-main {
    margin-top: 0;
}

.preview-purchase-grid {
    width: 100%;
    margin: 0;
    padding: 0;
}

.preview-product-body {
    position: relative;
    width: 100%;
    height: 104mm;
    min-height: 104mm;
    max-height: 104mm;
    overflow: hidden;

    border-left: 0.24mm solid var(--cd-document-border);
    border-right: 0.24mm solid var(--cd-document-border);
    background: #fff;
}

.preview-item-lines {
    width: 100%;
    height: 100%;
    min-height: 100%;
}

.preview-item-lines.measuring {
    height: auto !important;
    min-height: 0 !important;
}

.preview-item-lines .fill-row {
    height: 100%;
}

.preview-item-lines .fill-row td {
    height: 100%;
    padding: 0 !important;
    border-right: 0.24mm solid var(--cd-document-border) !important;
}

.preview-item-lines .fill-row td:last-child {
    border-right: 0 !important;
}

/* Keep the preview footer attached to the fixed 104 mm item body. */
.preview-document-main>.document-main-foot {
    width: 100%;
    margin-left: 0;
}

/* =========================================================
   PRINT SAFETY
   ========================================================= */

@media print {

    .po-preview-pages,
    .preview-prototype {
        display: none !important;
    }

    .cd-po-root.preview-ready .po-flow-source,
    .po-flow-source {
        display: block !important;
    }

    .page-flow-table>thead {
        display: table-header-group !important;
    }

    .page-flow-table>tfoot {
        display: table-footer-group !important;
    }

    .flow-item-fragment,
    .flow-item-fragment>td,
    .flow-item-table-wrap,
    .item-row,
    .item-row>td {
        page-break-inside: avoid !important;
        break-inside: avoid-page !important;
    }
}


/* =========================================================
   V4 MANUAL A4 PAGES - SINGLE PATH FOR PREVIEW AND PDF
   ========================================================= */
.manual-page {
    display: block !important;
}

.manual-item-lines .item-row,
.manual-item-lines .item-row>td {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

/* The visible item table is always exactly 104 mm high. */
.manual-page .preview-product-body {
    height: 104mm !important;
    min-height: 104mm !important;
    max-height: 104mm !important;
    overflow: hidden !important;
}

/* Real item rows occupy only the safe content budget; filler extends the
   column borders to the physical bottom of the 104 mm item area. */
.manual-page .manual-item-lines {
    width: 100%;
    height: 100%;
    min-height: 100%;
    table-layout: fixed;
}

.manual-page .manual-item-lines .fill-row {
    height: 100%;
}

.manual-page .manual-item-lines .fill-row td {
    height: 100%;
    padding: 0 !important;
    border-right: 0.24mm solid var(--cd-document-border) !important;
}

.manual-page .manual-item-lines .fill-row td:last-child {
    border-right: 0 !important;
}

@media print {
    .manual-page {
        display: block !important;
        page-break-after: always !important;
        break-after: page !important;
    }

    .manual-page.last-page {
        page-break-after: auto !important;
        break-after: auto !important;
    }
}


/* Workflow Action signature values are intentionally empty until a future action writes them. */
.order-signature-line,
.authorized-line {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 1mm;
    overflow: visible;
