}

.action-name {
    max-width: 52mm;
    overflow: hidden;
    font-size: 3.25mm;
    line-height: 3.7mm;
    text-overflow: ellipsis;
}

/*
 * Purchase Order page geometry.
 * Keep these values local: they must stay aligned with the pagination budget
 * passed to get_print_item_pages() in this format's HTML.
 */
.cd-po-root .manual-page.last-page .preview-product-body {
    height: 30mm !important;
    min-height: 30mm !important;
    max-height: 30mm !important;
}

/* The corporate header is absolute; normal-flow content starts below it. */
.cd-po.preview-page .document-main-head {
    margin-top: 52.30mm;
}

html:
{#
ERPNext Custom Print Format: Purchase Order
DocType: Purchase Order

Pagination strategy (v4):
- Every item is measured server-side with the printed font and column width.
- The Jinja template receives whole rows grouped into page-sized item tables.
- A row that does not fit moves to the next complete page.
#}

{% macro corporate_header(
company_name,
company_address,
company_contact,
tax_label,
tax_id,
branch,
document_title,
copy_title,
logo_src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg",
logo_alt="Connect Diagnostics"
) -%}
<header class="document-header cd-corporate-header">
    <img class="company-logo" src="{{ logo_src }}" alt="{{ logo_alt }}">
    <div class="company-name">{{ company_name }}</div>
    <div class="company-address">{{ company_address }}</div>
    <div class="company-contact">{{ company_contact }}</div>
    <div class="company-tax-label">{{ tax_label }}</div>
    <div class="company-tax-value">{{ tax_id }}</div>
    <div class="company-branch">{{ branch }}</div>
    <div class="document-title">{{ document_title }}</div>
    <div class="copy-title">{{ copy_title }}</div>
</header>
{%- endmacro %}

{% macro item_table(columns=(), classes="") -%}
    <table class="cd-table{% if classes %} {{ classes }}{% endif %}">
        {% if columns %}
            <colgroup>
                {% for class_name in columns %}
        <col{% if class_name %} class="{{ class_name }}"{% endif %}>
                    {% endfor %}
            </colgroup>
        {% endif %}
        {{ caller() }}
    </table>
{%- endmacro %}

{{ register_print(doc) }}

{# =========================================================
LANGUAGE
========================================================= #}
{% set requested_lang = frappe.form_dict.get("_lang") if frappe.form_dict else "" %}
{% set print_lang = (requested_lang or doc.get("language") or frappe.local.lang or "th") | lower %}
{% set is_en = print_lang[:2] == "en" %}
{% set print_actions = get_print_action_context(doc) %}
{% set ordered_action = print_actions.get("ordered", {}) %}
{% set authorized_action = print_actions.get("authorized", {}) %}

{% macro t(th, en) -%}
{{ en if is_en else th }}
{%- endmacro %}

{% macro summary_label(thai, english) -%}
<span class="summary-label-th">{{ thai }}</span>
<span class="summary-label-en">{{ english }}</span>
{%- endmacro %}

{% macro print_date(value) -%}
{% if value %}
{% if is_en %}
{{ frappe.utils.formatdate(value, "dd-MM-yyyy") }}
{% else %}
{{ format_date(value) }}
{% endif %}
{% endif %}
{%- endmacro %}


{# =========================================================
DOCUMENT DATA
========================================================= #}
{% set first_item = doc.items[0] if doc.items else none %}
{% set required_date = doc.schedule_date or (first_item.schedule_date if first_item else none) %}
{% set delivery_by = doc.get("custom_delivery_by") or doc.get("shipping_rule") or "" %}
{% set eta_date = doc.get("eta") or doc.get("custom_eta") or required_date %}
{% set incoterm = doc.incoterm or "" %}
{% set currency = doc.currency or "" %}

{% if is_en %}
{% set company_name = "Connect Diagnostics Co., Ltd." %}
{% set company_address = "1/57-58 Venice Di Iris, Soi Watcharaphon 2/7, Tha Raeng, Bang Khen, Bangkok 10220, Thailand"
%}
{% set company_tax_label = "Tax ID" %}
{% set company_branch = "Head Office" %}
{% else %}
{% set company_name = "บริษัท คอนเนคไดแอกโนสติกส์ จำกัด" %}
{% set company_address = "1/57-58 เวนิส ดี ไอริส ซอยวัชรพล 2/7 แขวงท่าแร้ง เขตบางเขน กรุงเทพฯ 10220" %}
{% set company_tax_label = "เลขประจำตัวผู้เสียภาษี" %}
{% set company_branch = "สำนักงานใหญ่" %}
{% endif %}

{% set supplier_name = doc.supplier_name or doc.supplier or "" %}
{% set supplier_address = doc.address_display or "" %}
{% set ship_to_address = doc.shipping_address_display or "" %}
{% set supplier_contact = doc.contact_display or doc.contact_person or "" %}
{% set remark_text = doc.terms or doc.get("remarks") or "" %}
{% set ordered_by_name = ordered_action.get("name", "") %}


{# =========================================================
CREDIT TERMS
========================================================= #}
{% set credit_days = (doc.payment_schedule[0].get("credit_days") or 0) if doc.payment_schedule else 0 %}

{% if credit_days %}
{% set credit_text = (credit_days ~ " Days") if is_en else (credit_days ~ " วัน") %}
{% elif doc.payment_terms_template %}
{% set credit_text = doc.payment_terms_template %}
{% else %}
{% set credit_text = "Cash" if is_en else "เงินสด" %}
{% endif %}


{# =========================================================
TOTALS
========================================================= #}
{% set gross_amount = (doc.total or 0) | float %}
{% set net_total = (doc.net_total if doc.net_total is not none else gross_amount) | float %}
{% set item_discount = gross_amount - net_total %}
{% set additional_discount = (doc.discount_amount or 0) | float %}
{% set discount_amount = item_discount + additional_discount %}
{% set after_discount = gross_amount - discount_amount %}
{% set vat_rate = (doc.taxes[0].rate or 0) if doc.taxes else 0 %}
{% set vat_amount = (doc.total_taxes_and_charges or 0) | float %}

{% if is_en %}
{% set amount_in_words = doc.in_words or "" %}
{% else %}
{% set amount_in_words = number_to_thai_currency(doc.grand_total or 0, doc.currency) %}
{% endif %}


{% macro product_head() -%}
<div class="product-head">
    <div class="head-cell col-no">{{ t("ลำดับ", "No.") }}</div>
    <div class="head-cell col-item-code">{{ t("รหัสสินค้า", "Item Code") }}</div>
    <div class="head-cell col-mat-code">{{ t("รหัสผู้จำหน่าย", "Mat. Code") }}</div>
    <div class="head-cell col-description">{{ t("รายละเอียด", "Description") }}</div>
    <div class="head-cell col-quantity">{{ t("จำนวน", "QTY") }}</div>
    <div class="head-cell col-uom">{{ t("หน่วย", "UOM") }}</div>
    <div class="head-cell col-unit-price">{{ t("หน่วยละ", "Unit Price") }}</div>
    <div class="head-cell col-amount">{{ t("จำนวนเงิน", "Amount") }}</div>
</div>
{%- endmacro %}

{% macro item_row(row) -%}
