            <div class="total-label">{{ summary_label("จำนวนเงินรวมทั้งสิ้น", "Grand Total") }}</div>
            <div class="total-value">{{ format_money(doc.grand_total) }}</div>
        </div>
    </section>

    <footer class="approval-box">
        <div class="approval-left">
            <div class="order-signature-line">
                {% if ordered_action.get("signature") %}<img class="action-signature-image"
                    src="{{ ordered_action.get("signature") | e }}" alt="">{% else %}<span
                    class="signature-placeholder" aria-hidden="true"></span>{% endif %}
            </div>
            <div class="order-date-line">{% if ordered_action.get("acted_at") %}{{
                print_date(ordered_action.get("acted_at")) }}{% endif %}</div>
            <div class="order-signature-caption">
                <span class="action-name">{{ ordered_by_name }}</span>
                <span class="signature-role">({{ t("ผู้สั่งซื้อสินค้า", "Ordered By") }})</span>
            </div>
            <div class="order-date-caption">{{ t("วันที่", "Date") }}</div>
        </div>

        <div class="approval-right">
            <div class="on-behalf">{{ t("ในนาม", "On behalf of") }}</div>
            <div class="signature-company">{{ company_name }}</div>
            <div class="authorized-line">
                {% if authorized_action.get("signature") %}<img class="action-signature-image"
                    src="{{ authorized_action.get("signature") | e }}" alt="">{% else %}<span
                    class="signature-placeholder" aria-hidden="true"></span>{% endif %}
            </div>
            <div class="authorized-caption">
                <span class="action-name">{{ authorized_action.get("name", "") }}</span>
                <span class="signature-role">({{ t("ผู้รับมอบอำนาจ", "Authorized Signature") }})</span>
            </div>
            <div class="authorized-date-line">{% if authorized_action.get("acted_at") %}{{
                print_date(authorized_action.get("acted_at")) }}{% endif %}</div>
            <div class="authorized-date-caption">{{ t("วันที่", "Date") }}</div>
        </div>
    </footer>
</div>
{%- endmacro %}



